# frozen_string_literal: true

module PaymentProviders
  class MastercardProvider < BaseProvider
    API_VERSION = "100"
    REGIONS = %w[ap eu na].freeze

    PROCESSING_STATUSES = %w[PENDING IN_PROGRESS].freeze
    SUCCESS_STATUSES = %w[CAPTURED AUTHORIZED].freeze
    FAILED_STATUSES = %w[FAILED EXPIRED CANCELLED DECLINED].freeze

    validates :merchant_id, presence: true
    validates :api_password, presence: true
    validates :region, presence: true, inclusion: {in: REGIONS}

    # NOTE: The notification secret is generated by the gateway (Merchant Administration >
    #       Webhook Notifications) and pasted back by the operator, so it is never generated here.
    secrets_accessors :merchant_id, :api_password, :webhook_secret
    settings_accessors :region, :test_mode

    def payment_type
      "mastercard"
    end

    def test_mode?
      ActiveModel::Type::Boolean.new.cast(test_mode) || false
    end

    # NOTE: Test transactions run on the same regional gateway as live ones.
    #       The gateway addresses the merchant test profile as TEST<merchant_id>.
    def gateway_merchant_id
      test_mode? ? "TEST#{merchant_id}" : merchant_id
    end

    def api_url
      "https://#{region}-gateway.mastercard.com/api/rest/version/#{API_VERSION}/merchant/#{gateway_merchant_id}"
    end

    def api_headers
      {
        "Authorization" => "Basic #{Base64.strict_encode64("merchant.#{gateway_merchant_id}:#{api_password}")}",
        "Content-Type" => "application/json",
        "Accept" => "application/json"
      }
    end
  end
end

